import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const migrationDirectory = resolve(root, 'apps/api/drizzle');
const journalPath = resolve(migrationDirectory, 'meta/_journal.json');
const generatedBundlePath = resolve(
  root,
  'apps/migration-worker/src/generated-migrations.ts',
);
const latestMigrationPath = resolve(
  root,
  'apps/api/src/db/latest-migration.ts',
);

export async function generateMigrationBundle(options = {}) {
  const directory = options.migrationDirectory ?? migrationDirectory;
  const journalFile = options.journalPath ?? journalPath;
  const bundleFile = options.generatedBundlePath ?? generatedBundlePath;
  const latestFile = options.latestMigrationPath ?? latestMigrationPath;

  const journal = parseJournal(await readFile(journalFile, 'utf8'));
  const sqlNames = (await readdir(directory))
    .filter((name) => /^\d{4}_.+\.sql$/u.test(name))
    .sort();
  const journalNames = journal.entries.map(({ tag }) => `${tag}.sql`);
  if (JSON.stringify(sqlNames) !== JSON.stringify(journalNames)) {
    throw new Error(
      'Drizzle migration SQL files must exactly match meta/_journal.json.',
    );
  }

  const migrations = [];
  for (const entry of journal.entries) {
    const sql = await readFile(resolve(directory, `${entry.tag}.sql`), 'utf8');
    migrations.push({
      tag: entry.tag,
      folderMillis: entry.when,
      hash: createHash('sha256').update(sql).digest('hex'),
      statements: sql.split('--> statement-breakpoint'),
    });
  }

  const latest = migrations.at(-1);
  if (latest === undefined) throw new Error('No Drizzle migrations were found.');

  const bundleSource = [
    '// Generated by scripts/generate-migration-bundle.mjs. Do not edit manually.',
    "import type { MigrationDefinition } from './migrate.js';",
    '',
    `export const migrationBundle = ${JSON.stringify(migrations, null, 2)} as const satisfies readonly MigrationDefinition[];`,
    '',
  ].join('\n');
  const latestSource = [
    '// Generated by scripts/generate-migration-bundle.mjs. Do not edit manually.',
    'export const latestMigrationHash =',
    `  '${latest.hash}';`,
    '',
  ].join('\n');

  await Promise.all([
    writeFile(bundleFile, bundleSource, 'utf8'),
    writeFile(latestFile, latestSource, 'utf8'),
  ]);

  return { migrations, latest };
}

function parseJournal(text) {
  const value = JSON.parse(text);
  if (
    typeof value !== 'object' ||
    value === null ||
    value.dialect !== 'postgresql' ||
    !Array.isArray(value.entries) ||
    value.entries.length === 0
  ) {
    throw new Error('Drizzle migration journal is invalid.');
  }

  let previousWhen = -1;
  const tags = new Set();
  const entries = value.entries.map((entry, index) => {
    if (
      typeof entry !== 'object' ||
      entry === null ||
      entry.idx !== index ||
      typeof entry.tag !== 'string' ||
      !/^\d{4}_.+/u.test(entry.tag) ||
      tags.has(entry.tag) ||
      !Number.isSafeInteger(entry.when) ||
      entry.when <= previousWhen ||
      entry.breakpoints !== true
    ) {
      throw new Error(
        `Drizzle migration journal entry ${String(index)} is invalid.`,
      );
    }
    tags.add(entry.tag);
    previousWhen = entry.when;
    return { tag: entry.tag, when: entry.when };
  });
  return { entries };
}

const invokedPath = process.argv[1];
if (
  invokedPath !== undefined &&
  import.meta.url === pathToFileURL(resolve(invokedPath)).href
) {
  const result = await generateMigrationBundle();
  globalThis.console.log(
    `Generated ${String(result.migrations.length)} migrations; latest is ${result.latest.tag}.`,
  );
}
